-- TIMED OUT (26 Nov). Not used; Blizzard cells were run per day with 12b_final_cells_slim.sql (raw/19_blizzard_cells_by_day.txt).
-- Blizzard ROW Registration K2, replay 9-11 Nov 2026 in one scan, per (dict, group) cell summed over the 3 days.
-- = 11_replay_confirm_template.sql with per-replay-day share (7 days before each day, as 06_ in the previous run) and per-day LT volume
-- (previous UTC day's sessions joined by date), + 12_final_cells.sql. LT current threshold 1,500.
WITH bd AS (SELECT TO_DATE(session_ts) dy, di_matched_signature_at_session_created ms, COUNT(*) c FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-02' AND session_last_timestamp<'2026-11-12 06:00' AND session_ts>='2026-11-02' AND session_ts<'2026-11-11' AND COALESCE(latest_risk_band,'')<>'High' GROUP BY 1,2), rd AS (SELECT column1::DATE rday FROM VALUES ('2026-11-09'),('2026-11-10'),('2026-11-11')), sh0 AS (SELECT rday, ms, SUM(c) c FROM bd JOIN rd ON bd.dy>=DATEADD(day,-7,rday) AND bd.dy<rday GROUP BY 1,2), sh AS (SELECT rday, ms, c/SUM(c) OVER (PARTITION BY rday) share FROM sh0), pd AS (SELECT TO_DATE(session_ts) dy, COUNT(*) pdn FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-08' AND session_last_timestamp<'2026-11-12 06:00' AND session_ts>='2026-11-08' AND session_ts<'2026-11-11' GROUP BY 1), a0 AS (SELECT session sid, session_ts ts, di_dictionary_num_matched_at_session_created d, di_matched_signature_at_session_created ms, os_at_session_created os, COALESCE(webgl_unmasked_renderer_at_session_created,'') r, COALESCE(cdn__ja4_hash_at_session_created,'') ja4, COALESCE(ua_at_session_created,'') ua, user_ip_at_session_created ip, cdn__asn_at_session_created asn, latest_isp isp, IFF(latest_risk_band='High',1,0) hi, IFF(sessions_verified>0,1,0) ver, IFF(was_challenged>0,1,0) chl, IFF(was_challenged>0 AND COALESCE(sessions_solved,0)=0,1,0) chns, di_short_term_count_at_session_created stc, di_long_term_count_at_session_created ltc, IFF(di_short_term_threshold_breached_at_session_created,1,0) stb, IFF(di_long_term_threshold_breached_at_session_created,1,0) ltb, TIME_SLICE(session_ts,20,'MINUTE') b20 FROM ARK_PROD.STARFLEET.PROD_INT_SESSION_SUMMARY WHERE public_key='E8A75615-1CBA-5DFF-8032-D16BCF234E10' AND session_last_timestamp>='2026-11-08 23:40' AND session_last_timestamp<'2026-11-12 06:00' AND session_ts>='2026-11-08 23:40' AND session_ts<'2026-11-12 00:00'), bc AS (SELECT b20, COUNT(*) bn FROM a0 GROUP BY 1), a1 AS (SELECT a0.*, COUNT(*) OVER (PARTITION BY a0.b20 ORDER BY ts, sid ROWS UNBOUNDED PRECEDING) + COALESCE(p.bn,0) vol FROM a0 LEFT JOIN bc p ON p.b20 = DATEADD(minute,-20,a0.b20)), a2 AS (SELECT a1.*, COUNT(*) OVER (PARTITION BY TO_DATE(ts) ORDER BY ts, sid ROWS UNBOUNDED PRECEDING) + pd.pdn lvol FROM a1 JOIN pd ON pd.dy=DATEADD(day,-1,TO_DATE(a1.ts)) WHERE ts>='2026-11-09 00:00'), s1 AS (SELECT a2.*, CASE WHEN r ILIKE '%SwiftShader%' OR r ILIKE '%llvmpipe%' OR r ILIKE '%VirtualBox%' OR r ILIKE '%VMware%' THEN 'A' WHEN r ILIKE '%Basic Render Driver%' AND COALESCE(os,'')<>'Windows' THEN 'B' WHEN COALESCE(os,'') IN ('','--') AND r<>'' THEN 'B' WHEN ja4 LIKE 't%' AND SPLIT_PART(ja4,'_',2) IN ('a09f3c656075','2802a3db6c62') AND os IN ('Windows','GNU/Linux','Ubuntu','Chrome OS') THEN 'C' WHEN ua LIKE '%Chrome/%' AND RIGHT(SPLIT_PART(ja4,'_',1),2)='h1' THEN 'C' WHEN TRY_TO_NUMBER(REGEXP_SUBSTR(ua,'Chrome/([0-9]+)',1,1,'e',1))>=70 AND ja4 LIKE 't12%' THEN 'C' END AS x, CASE WHEN r ILIKE '%Basic Render Driver%' AND os='Windows' THEN 'WinRDVM' WHEN os IN ('Windows','OS X','Chrome OS') THEN 'Desktop' WHEN os IN ('iOS','iPadOS','Android') THEN 'Mobile' WHEN os IN ('GNU/Linux','Ubuntu') THEN 'Linux' ELSE 'Other' END AS grp0, COALESCE(sh.share,0) share, CASE WHEN d IN (1,3) THEN 1 WHEN d=7 THEN 1.5 ELSE 2 END dfac, CASE WHEN d IN (1,3) THEN 1 WHEN d=7 THEN 2 WHEN d IN (15,31) THEN 4 ELSE 6 END dlt FROM a2 LEFT JOIN sh ON sh.ms=a2.ms AND sh.rday=TO_DATE(a2.ts) WHERE a2.d IS NOT NULL), s2 AS (SELECT s1.*, IFF(x IS NULL, grp0, 'SKIP_'||x) grp, IFF(x IS NULL AND ms IS NOT NULL AND d>0, 1, 0) elig, IFF(SUM(hi) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) / COUNT(*) OVER (PARTITION BY x, grp0, ms, TIME_SLICE(ts,40,'MINUTE')) < 0.2, 1, 0) cl FROM s1), s3 AS (SELECT s2.*, stb r0, ltb r1, GREATEST(stb,ltb) r2, IFF(elig=1 AND stc > GREATEST(11, share*vol*5*dfac),1,0) r3, IFF(elig=1 AND stc > GREATEST(8, share*vol*5*dfac),1,0) r4, IFF(elig=1 AND stc > GREATEST(8, share*vol*10*dfac),1,0) r5, IFF(elig=1 AND stc > GREATEST(5, share*vol*5*dfac),1,0) r6, IFF(elig=1 AND stc > GREATEST(11, share*vol*10*dfac),1,0) r7, IFF(elig=1 AND ltc > GREATEST(LEAST(660,1500), share*lvol*5*dlt),1,0) r8, IFF(elig=1 AND ltc > GREATEST(LEAST(480,1500), share*lvol*5*dlt),1,0) r9 FROM s2), s4 AS (SELECT s3.*, GREATEST(r3,r8) r10, GREATEST(r4,r9) r11 FROM s3) SELECT COALESCE(d::STRING,'ALL')||'|'||COALESCE(grp,'ALL')||'|'||COUNT(*)||'|'||SUM(cl)||'|'||SUM(r0)||','||SUM(r0*hi)||','||SUM(r0*ver)||','||SUM(r0*chl)||','||SUM(r0*chns)||','||SUM(r0*cl)||','||SUM(r0*(1-r0))||','||SUM(r0*(1-r0))||','||SUM(r0*cl*hi)||'|'||SUM(r1)||','||SUM(r1*hi)||','||SUM(r1*ver)||','||SUM(r1*chl)||','||SUM(r1*chns)||','||SUM(r1*cl)||','||SUM(r1*(1-r0))||','||SUM(r0*(1-r1))||','||SUM(r1*cl*hi)||'|'||SUM(r2)||','||SUM(r2*hi)||','||SUM(r2*ver)||','||SUM(r2*chl)||','||SUM(r2*chns)||','||SUM(r2*cl)||','||SUM(r2*(1-r0))||','||SUM(r0*(1-r2))||','||SUM(r2*cl*hi)||'|'||SUM(r3)||','||SUM(r3*hi)||','||SUM(r3*ver)||','||SUM(r3*chl)||','||SUM(r3*chns)||','||SUM(r3*cl)||','||SUM(r3*(1-r0))||','||SUM(r0*(1-r3))||','||SUM(r3*cl*hi)||'|'||SUM(r4)||','||SUM(r4*hi)||','||SUM(r4*ver)||','||SUM(r4*chl)||','||SUM(r4*chns)||','||SUM(r4*cl)||','||SUM(r4*(1-r0))||','||SUM(r0*(1-r4))||','||SUM(r4*cl*hi)||'|'||SUM(r5)||','||SUM(r5*hi)||','||SUM(r5*ver)||','||SUM(r5*chl)||','||SUM(r5*chns)||','||SUM(r5*cl)||','||SUM(r5*(1-r0))||','||SUM(r0*(1-r5))||','||SUM(r5*cl*hi)||'|'||SUM(r6)||','||SUM(r6*hi)||','||SUM(r6*ver)||','||SUM(r6*chl)||','||SUM(r6*chns)||','||SUM(r6*cl)||','||SUM(r6*(1-r0))||','||SUM(r0*(1-r6))||','||SUM(r6*cl*hi)||'|'||SUM(r7)||','||SUM(r7*hi)||','||SUM(r7*ver)||','||SUM(r7*chl)||','||SUM(r7*chns)||','||SUM(r7*cl)||','||SUM(r7*(1-r0))||','||SUM(r0*(1-r7))||','||SUM(r7*cl*hi)||'|'||SUM(r8)||','||SUM(r8*hi)||','||SUM(r8*ver)||','||SUM(r8*chl)||','||SUM(r8*chns)||','||SUM(r8*cl)||','||SUM(r8*(1-r1))||','||SUM(r1*(1-r8))||','||SUM(r8*cl*hi)||'|'||SUM(r9)||','||SUM(r9*hi)||','||SUM(r9*ver)||','||SUM(r9*chl)||','||SUM(r9*chns)||','||SUM(r9*cl)||','||SUM(r9*(1-r1))||','||SUM(r1*(1-r9))||','||SUM(r9*cl*hi)||'|'||SUM(r10)||','||SUM(r10*hi)||','||SUM(r10*ver)||','||SUM(r10*chl)||','||SUM(r10*chns)||','||SUM(r10*cl)||','||SUM(r10*(1-r2))||','||SUM(r2*(1-r10))||','||SUM(r10*cl*hi)||'|'||SUM(r11)||','||SUM(r11*hi)||','||SUM(r11*ver)||','||SUM(r11*chl)||','||SUM(r11*chns)||','||SUM(r11*cl)||','||SUM(r11*(1-r2))||','||SUM(r2*(1-r11))||','||SUM(r11*cl*hi) r FROM s4 GROUP BY d, grp HAVING SUM(r2+r3+r4+r5+r6+r7+r8+r9)>0
